const faqTranslations:Record<Exclude<L,"en">,Copy["faq"]>={fr:[["Que dit LoloBuy faire ?","Sa page publique décrit une aide à l’achat sur des canaux chinois en ligne et hors ligne."],["Puis-je commencer avec un lien ?","La page indique qu’un visiteur peut coller un lien produit pour commencer. Vérifiez d’abord l’annonce actuelle."],["Où vont les marchandises ?","La page indique un envoi vers l’entrepôt chinois de LoloBuy, pas la livraison finale."],["Un lien garantit-il la disponibilité ?","Non. Stock, options, réponse du vendeur et détails peuvent changer."],["Le prix affiché est-il final ?","Pas forcément. Produit, transport, service et frais de destination peuvent être séparés."],["Ce site peut-il promettre livraison ou douane ?","Non. Cela dépend du colis, du pays, du transporteur et des règles locales."],["Les images prouvent-elles qualité ou authenticité ?","Non. Elles montrent des détails visibles sans garantir taille, matière, durabilité, authenticité ou livraison."],["Ce guide traite-t-il commandes ou paiements ?","Non. C’est un guide de recherche indépendant."],["Que sauvegarder avant commande ?","URL, titre, variante choisie, prix, vendeur, date, mesures et questions ouvertes."],["Où continuer la recherche ?","Utilisez FindSpreadsheet, puis vérifiez l’annonce source actuelle avant de décider."]],de:[["Was sagt LoloBuy über seinen Dienst?","Die öffentliche Startseite beschreibt Hilfe beim Kauf über chinesische Online- und Offline-Kanäle."],["Kann ich mit einem Produktlink beginnen?","Die Startseite sagt, dass ein Produktlink eingefügt werden kann. Prüfen Sie zuerst das aktuelle Angebot."],["Wohin werden Waren gesendet?","Die Startseite nennt das LoloBuy-China-Lager, nicht die Lieferung an den Endort."],["Garantiert ein Link Verfügbarkeit?","Nein. Bestand, Optionen, Verkäuferantwort und Angaben können sich ändern."],["Ist der angezeigte Preis endgültig?","Nicht unbedingt. Produkt-, Versand-, Service- und Zielkosten können getrennt sein."],["Kann diese Seite Lieferung oder Zoll garantieren?","Nein. Das hängt von Paket, Ziel, Transporteur und lokalen Regeln ab."],["Beweisen Bilder Qualität oder Echtheit?","Nein. Sie zeigen sichtbare Details, garantieren aber nicht Passform, Material, Haltbarkeit, Echtheit oder Lieferung."],["Bearbeitet dieser Leitfaden Bestellungen oder Zahlungen?","Nein. Er ist ein unabhängiger Rechercheleitfaden."],["Was sollte ich vor der Bestellung speichern?","URL, Titel, gewählte Variante, Preis, Verkäufer, Datum, Maße und offene Fragen."],["Wo kann ich weiter recherchieren?","Nutzen Sie FindSpreadsheet und prüfen Sie danach das aktuelle Quellangebot."]],es:[["¿Qué dice LoloBuy que hace?","Su página pública describe ayuda para comprar en canales chinos online y offline."],["¿Puedo empezar con un enlace?","La página dice que se puede pegar un enlace de producto para iniciar. Confirma primero el anuncio actual."],["¿A dónde se envían los productos?","La página indica el almacén de LoloBuy en China, no la entrega final."],["¿Un enlace garantiza disponibilidad?","No. Stock, opciones, respuesta del vendedor y detalles pueden cambiar."],["¿El precio mostrado es final?","No necesariamente. Producto, envío, servicio y cargos de destino pueden ser separados."],["¿Este sitio puede prometer entrega o aduanas?","No. Depende del paquete, destino, transportista y reglas locales."],["¿Las imágenes prueban calidad o autenticidad?","No. Muestran detalles visibles, pero no garantizan ajuste, material, durabilidad, autenticidad o entrega."],["¿Esta guía procesa pedidos o pagos?","No. Es una guía de investigación independiente."],["¿Qué guardo antes de pedir?","URL, título, variante elegida, precio, vendedor, fecha, medidas y preguntas abiertas."],["¿Dónde sigo investigando?","Usa FindSpreadsheet y revisa el anuncio fuente actual antes de decidir."]],it:[["Cosa dice di fare LoloBuy?","La sua pagina pubblica descrive assistenza per acquisti da canali cinesi online e offline."],["Posso iniziare con un link?","La pagina dice che si può incollare un link prodotto per iniziare. Verifica prima l’annuncio attuale."],["Dove vengono inviati i beni?","La pagina indica il magazzino LoloBuy in Cina, non la consegna finale."],["Un link garantisce disponibilità?","No. Stock, opzioni, risposta del venditore e dettagli possono cambiare."],["Il prezzo mostrato è finale?","Non necessariamente. Prodotto, spedizione, servizio e oneri di destinazione possono essere separati."],["Questo sito promette consegna o dogana?","No. Dipendono da pacco, destinazione, vettore e regole locali."],["Le immagini provano qualità o autenticità?","No. Mostrano dettagli visibili ma non garantiscono vestibilità, materiale, durata, autenticità o consegna."],["Questa guida gestisce ordini o pagamenti?","No. È una guida di ricerca indipendente."],["Cosa salvo prima di ordinare?","URL, titolo, variante scelta, prezzo, venditore, data, misure e domande aperte."],["Dove continuo la ricerca?","Usa FindSpreadsheet, poi controlla l’annuncio fonte attuale prima di decidere."]],nl:[["Wat zegt LoloBuy dat het doet?","De openbare startpagina beschrijft hulp bij aankopen via Chinese online- en offlinekanalen."],["Kan ik met een productlink beginnen?","De startpagina zegt dat een productlink kan worden geplakt. Controleer eerst de actuele aanbieding."],["Waarheen gaan de goederen?","De startpagina noemt het LoloBuy-magazijn in China, niet de eindbestemming."],["Garandeert een link beschikbaarheid?","Nee. Voorraad, opties, verkopersreactie en details kunnen veranderen."],["Is de getoonde prijs definitief?","Niet noodzakelijk. Product-, verzend-, service- en bestemmingskosten kunnen apart zijn."],["Kan deze site bezorging of douane beloven?","Nee. Dat hangt af van pakket, bestemming, vervoerder en lokale regels."],["Bewijzen beelden kwaliteit of echtheid?","Nee. Ze tonen zichtbare details maar garanderen geen pasvorm, materiaal, duurzaamheid, echtheid of bezorging."],["Verwerkt deze gids bestellingen of betalingen?","Nee. Het is een onafhankelijke onderzoeksgids."],["Wat bewaar ik vóór bestellen?","URL, titel, gekozen variant, prijs, verkoper, datum, maten en open vragen."],["Waar kan ik verder onderzoeken?","Gebruik FindSpreadsheet en controleer daarna de actuele bronaanbieding."]],pl:[["Co LoloBuy mówi, że robi?","Publiczna strona opisuje pomoc w zakupach z chińskich kanałów online i offline."],["Czy mogę zacząć od linku?","Strona mówi, że można wkleić link produktu, aby rozpocząć. Najpierw sprawdź aktualne ogłoszenie."],["Dokąd wysyłane są towary?","Strona wskazuje magazyn LoloBuy w Chinach, a nie dostawę końcową."],["Czy link gwarantuje dostępność?","Nie. Stan, opcje, odpowiedź sprzedawcy i szczegóły mogą się zmienić."],["Czy widoczna cena jest ostateczna?","Niekoniecznie. Koszt produktu, wysyłki, usługi i opłaty docelowe mogą być osobne."],["Czy ta strona może obiecać dostawę lub cło?","Nie. Zależą one od paczki, celu, przewoźnika i lokalnych zasad."],["Czy zdjęcia potwierdzają jakość lub autentyczność?","Nie. Pokazują szczegóły widoczne, lecz nie gwarantują dopasowania, materiału, trwałości, autentyczności ani dostawy."],["Czy ten przewodnik obsługuje zamówienia lub płatności?","Nie. To niezależny przewodnik badawczy."],["Co zapisać przed zamówieniem?","URL, tytuł, wybrany wariant, cenę, sprzedawcę, datę, wymiary i otwarte pytania."],["Gdzie kontynuować badanie?","Użyj FindSpreadsheet, a potem sprawdź aktualne ogłoszenie źródłowe."]],pt:[["O que a LoloBuy diz fazer?","A página pública descreve assistência para compras em canais chineses online e offline."],["Posso começar com um link?","A página diz que pode colar um link de produto para começar. Confirme primeiro o anúncio atual."],["Para onde vão os bens?","A página indica o armazém LoloBuy na China, não a entrega final."],["Um link garante disponibilidade?","Não. Stock, opções, resposta do vendedor e detalhes podem mudar."],["O preço mostrado é final?","Não necessariamente. Produto, envio, serviço e encargos de destino podem ser separados."],["Este site pode prometer entrega ou alfândega?","Não. Dependem da encomenda, destino, transportadora e regras locais."],["Imagens provam qualidade ou autenticidade?","Não. Mostram detalhes visíveis, mas não garantem tamanho, material, durabilidade, autenticidade ou entrega."],["Este guia processa pedidos ou pagamentos?","Não. É um guia de pesquisa independente."],["O que devo guardar antes de pedir?","URL, título, variante escolhida, preço, vendedor, data, medidas e perguntas em aberto."],["Onde continuo a pesquisar?","Use FindSpreadsheet e depois verifique o anúncio de origem atual."]],sv:[["Vad säger LoloBuy att tjänsten gör?","Den offentliga startsidan beskriver hjälp med köp från kinesiska online- och offlinekanaler."],["Kan jag börja med en produktlänk?","Startsidan säger att en produktlänk kan klistras in för att börja. Kontrollera aktuell annons först."],["Vart skickas varorna?","Startsidan anger LoloBuys Kina-lager, inte leverans till slutdestination."],["Garanterar en länk tillgänglighet?","Nej. Lagerstatus, val, säljarens svar och detaljer kan ändras."],["Är visat pris slutgiltigt?","Inte nödvändigtvis. Produkt-, frakt-, service- och destinationskostnader kan vara separata."],["Kan denna sida lova leverans eller tullresultat?","Nej. Det beror på paket, destination, transportör och lokala regler."],["Bevisar bilder kvalitet eller äkthet?","Nej. De visar synliga detaljer men garanterar inte passform, material, hållbarhet, äkthet eller leverans."],["Hantera guiden beställningar eller betalningar?","Nej. Den är en oberoende forskningsguide."],["Vad ska jag spara före beställning?","URL, titel, vald variant, pris, säljare, datum, mått och öppna frågor."],["Var kan jag fortsätta undersöka?","Använd FindSpreadsheet och kontrollera sedan aktuell källannons."]]};
