// The article is authored as sixteen paired research checks.  Rendering each pair
// together creates the requested eight-chapter reading path without inventing
// filler copy for a particular language.  Every locale follows the same pairs.
const eightChapters=(sections:Copy["sections"]):Copy["sections"]=>Array.from({length:8},(_,i)=>{
const first=sections[i*2],second=sections[i*2+1];
return [`${first[0]} — ${second[0]}`,`${first[1]} ${second[1]}`];
});
// One canonical set of sixteen research checks.  The four clarifications are
// translated in every locale, so switching language keeps every information
// point instead of replacing a full paragraph with a shorter summary.
